template.solver:
def solve(a, b, c, d, e):
    nums = [a, b, c, d, e]
    ops_all = ['+', '-', '*', '/']
    best = None
    for o1 in ops_all:
        for o2 in ops_all:
            for o3 in ops_all:
                for o4 in ops_all:
                    ops = [o1, o2, o3, o4]
                    if len(set(ops)) != 4:
                        continue
                    total = 0
                    sign = 1
                    cur = nums[0]
                    valid = True
                    for i in range(4):
                        op = ops[i]
                        n = nums[i + 1]
                        if op == '*':
                            cur = cur * n
                        elif op == '/':
                            if n == 0:
                                valid = False
                                break
                            cur = cur / n
                        else:
                            total = total + sign * cur
                            sign = 1 if op == '+' else -1
                            cur = n
                    if not valid:
                        continue
                    total = total + sign * cur
                    if abs(total - round(total)) < 1e-9:
                        val = int(round(total))
                        if best is None or val > best:
                            best = val
    if best is None:
        return 0
    return best
